# Noto Sans Khmer (SIL Open Font License 1.1, (c) The Noto Project Authors), Khmer letters only. Embedded so the list looks right on every computer.
_FONT_400 = ""
_FONT_700 = ""


# ============================================================ editing (writes to the attendance Excel; the app makes a safe copy first and reads every cell back)
EDIT_FIELDS = [("Day hours", "dayhours"), ("Night hours", "nighthours"), ("SW", "sw"), ("Late / early (min)", "l/e"),
               ("OT day x1.5 (a)", "(a)dayotx1.5"), ("OT night x2 (a)", "(a)nightotx2"), ("Holiday OT (b)", "(b)holidayot"), ("Night holiday OT (n)", "(n)holidayot"),
               ("Extra OT 1.5 (c)", "(c)ot1.5"), ("Extra OT 2 (c)", "(c)ot2"), ("Sunday OT 2 (d)", "(d)ot2"), ("Night Sunday OT 2 (n)", "(n)ot2"), ("Code", "code")]
CV_FIELDS = [("Department", 3), ("Job title", 4), ("Khmer name", 5), ("English name", 6)]


def apply_edits(path, edits, backup_dir):
    """edits = [{type:'cell', wid, day, key, new} | {type:'cv', wid, col, new}]. Returns (n_changed, problems, bad_readback).
    A cell that holds a FORMULA is never overwritten. The original file is copied to backup_dir first."""
    import shutil
    from datetime import datetime
    wb = openpyxl.load_workbook(path)
    ws, cv = wb[SHEET], wb["CV"]
    blocks = sorted((m for m in ws.merged_cells.ranges if m.min_row == 5), key=lambda m: m.min_col)
    cols_of = [{_norm(ws.cell(7, c).value): c for c in range(b.min_col, b.max_col + 1)} for b in blocks]
    rows = {str(ws.cell(r, 1).value).strip(): r for r in range(8, ws.max_row + 1) if ws.cell(r, 1).value}
    cvrows = {str(cv.cell(r, 2).value).strip(): r for r in range(3, cv.max_row + 1) if cv.cell(r, 2).value}
    todo, problems = [], []
    for e in edits:
        if e["type"] == "cell":
            r, k = rows.get(e["wid"]), e["day"] - 1
            c = cols_of[k].get(e["key"]) if 0 <= k < len(cols_of) else None
            if not r or not c:
                problems.append(f"{e['wid']} day {e['day']}: place not found in the Excel")
                continue
            cell = ws.cell(r, c)
        else:
            r = cvrows.get(e["wid"])
            if not r:
                problems.append(f"{e['wid']}: not found in sheet CV")
                continue
            cell = cv.cell(r, e["col"])
        if isinstance(cell.value, str) and cell.value.startswith("=") or type(cell.value).__name__ == "ArrayFormula":
            problems.append(f"{cell.coordinate} ({e['wid']}) holds a formula: not changed")
            continue
        new = e["new"]
        todo.append((cell, ("CV" if e["type"] == "cv" else SHEET), new))
    for cell, _, new in todo:
        cell.value = new
    os.makedirs(backup_dir, exist_ok=True)
    shutil.copy(path, os.path.join(backup_dir, os.path.basename(path).rsplit(".", 1)[0] + f"_edit_{datetime.now():%Y%m%d_%H%M%S}.xlsx"))
    wb.save(path)
    chk = openpyxl.load_workbook(path)
    bad = [(c.coordinate, new, chk[sh][c.coordinate].value) for c, sh, new in todo if (chk[sh][c.coordinate].value or None) != (new or None)]
    return len(todo), problems, bad
